/*
 Problem: 3312. Sorted GCD Pair Queries
 Language: cpp
 Runtime: 51 ms (33.25%)
 Memory: 131.7 MB (41.37%)
 Tags: Array, Hash Table, Math, Binary Search, Combinatorics, Counting, Number Theory, Prefix Sum, Euclidean Algorithm, Greatest Common Divisor
*/
class Solution {
public:
    vector<int> gcdValues(vector<int>& nums, vector<long long>& queries) {
        int maxValue = *max_element(nums.begin(), nums.end());

        vector<int> freq(maxValue + 1);
        for (int x : nums) {
            freq[x]++;
        }

        vector<long long> divisible(maxValue + 1);
        for (int d = 1; d <= maxValue; d++) {
            for (int multiple = d; multiple <= maxValue; multiple += d) {
                divisible[d] += freq[multiple];
            }
        }

        vector<long long> gcdCount(maxValue + 1);
        for (int d = maxValue; d >= 1; d--) {
            long long cnt = divisible[d];
            gcdCount[d] = cnt * (cnt - 1) / 2;

            for (int multiple = d * 2; multiple <= maxValue; multiple += d) {
                gcdCount[d] -= gcdCount[multiple];
            }
        }

        vector<long long> prefix(maxValue + 1);
        for (int d = 1; d <= maxValue; d++) {
            prefix[d] = prefix[d - 1] + gcdCount[d];
        }

        vector<int> answer;
        answer.reserve(queries.size());

        for (long long query : queries) {
            answer.push_back(
                lower_bound(prefix.begin() + 1, prefix.end(), query + 1) - prefix.begin()
            );
        }

        return answer;
    }
};
